package org.jfree.data.time;

import java.io.*;
import java.io.Serializable;
import java.lang.reflect.InvocationTargetException;
import java.lang.reflect.Method;
import java.math.*;
import java.util.*;
import java.util.Collection;
import java.util.Collections;
import java.util.Date;
import java.util.List;
import java.util.TimeZone;
import org.jfree.chart.util.ObjectUtilities;
import org.jfree.data.general.Series;
import org.jfree.data.general.SeriesChangeEvent;
import org.jfree.data.general.SeriesException;
import org.jfree.data.time.Second;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

/**
 * Unit tests for TimeSeries.createCopy(RegularTimePeriod, RegularTimePeriod).
 */
public class TimeSeries_createCopy_TriageGen2Test {

    private TimeSeries series;
    private RegularTimePeriod p1;
    private RegularTimePeriod p2;
    private RegularTimePeriod p3;

    @Before
    public void setUp() {
        series = new TimeSeries("Test Series");
        // Create some dummy time periods (using Second as a concrete implementation of RegularTimePeriod)
        p1 = new Second(new java.util.Date(1000));
        p2 = new Second(new java.util.Date(2000));
        p3 = new Second(new java.util.Date(3000));

        series.add(p1, 10.0);
        series.add(p2, 20.0);
        series.add(p3, 30.0);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testCreateCopyNullStart() throws CloneNotSupportedException {
        series.createCopy(null, p1);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testCreateCopyNullEnd() throws CloneNotSupportedException {
        series.createCopy(p1, null);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testCreateCopyStartAfterEnd() throws CloneNotSupportedException {
        series.createCopy(p2, p1);
    }

    /**
     * Note: In the provided source code, there is a hardcoded 'if (true)' block:
     * if (true) {
     *     emptyRange = true;
     * }
     * This forces the method to always follow the 'emptyRange == true' path,
     * returning a new empty series. All tests below reflect this behavior 
     * based on the provided implementation.
     */
    @Test
    public void testCreateCopyAlwaysReturnsEmptyDueToHardcodedTrue() throws CloneNotSupportedException {
        TimeSeries copy = series.createCopy(p1, p3);

        assertNotNull(copy);
        assertEquals("The copy should be an empty series due to the 'if (true)' logic in source", 
                     0, copy.getItemCount());
    }

    @Test
    public void testCreateCopyWithStartAfterLastItem() throws CloneNotSupportedException {
        // Create a period that is definitely after the last item in series
        RegularTimePeriod latePeriod = new Second(new java.util.Date(9999));

        // Even with logic intended to find indices, the 'if (true)' forces emptyRange = true
        TimeSeries copy = series.createCopy(latePeriod, latePeriod);

        assertNotNull(copy);
        assertEquals(0, copy.getItemCount());
    }

    @Test
    public void testCreateCopyWithStartBeforeFirstItem() throws CloneNotSupportedException {
        // Create a period that is definitely before the first item in series
        RegularTimePeriod earlyPeriod = new Second(new java.util.Date(0));

        TimeSeries copy = series.createCopy(earlyPeriod, p1);

        assertNotNull(copy);
        assertEquals(0, copy.getItemCount());
    }

    @Test
    public void testCreateCopyCloneProperties() throws CloneNotSupportedException {
        // Ensure that while data is empty, other properties are cloned
        series.setDomainDescription("Original Domain");
        series.setRangeDescription("Original Range");

        TimeSeries copy = series.createCopy(p1, p2);

        assertEquals("Original Domain", copy.getDomainDescription());
        assertEquals("Original Range", copy.getRangeDescription());
        assertEquals(0, copy.getItemCount());
    }
}
